-- ParadiseRP - toutes les familles de blocs completes actuellement disponibles
SET NAMES utf8mb4;
START TRANSACTION;
ON DUPLICATE KEY UPDATE parent_id=VALUES(parent_id),caption_save=VALUES(caption_save),caption=VALUES(caption),order_num=VALUES(order_num),visible='1',enabled='1';
DELETE FROM catalog_items WHERE page_id BETWEEN 9967601 AND 9967607;
COMMIT;
